 function stopRecording(discard=false){recordRequest++;recordPending=false;clearTimeout(recordTimer);if(recorder?.state==='recording'){recordEnding=!discard;if(discard){recordCapture++;recorder.onstop=null}recorder.stop()}if(discard){recordCapture++;recordEnding=false;recordMeta=null}stream?.getTracks().forEach(t=>t.stop());stream=null;recording=false;if(discard&&recordURL){URL.revokeObjectURL(recordURL);recordURL=null}if(discard)recordBlob=null;recordChunks=discard?[]:recordChunks;}
 function renderLessonInteraction(selector){
  if(view!=='lesson'){render();return;}
  const source=selector?document.querySelector(selector):document.activeElement,x=scrollX,y=scrollY,top=source?.getBoundingClientRect().top,previousHeight=main.querySelector('.focused-lesson')?.getBoundingClientRect().height;
  const details=[...main.querySelectorAll('.focused-lesson details')].map((el,i)=>el.open?i:-1).filter(i=>i>=0),scrollRoot=document.documentElement,anchoring=scrollRoot.style.overflowAnchor;
  scrollRoot.style.overflowAnchor='none';render();
  const freshDetails=[...main.querySelectorAll('.focused-lesson details')];details.forEach(i=>{if(freshDetails[i])freshDetails[i].open=true;});
  const panel=main.querySelector('.focused-lesson');if(panel&&Number.isFinite(previousHeight))panel.style.minHeight=Math.ceil(previousHeight)+'px';
  const target=selector?document.querySelector(selector):null;target?.focus({preventScroll:true});
  const position=target&&Number.isFinite(top)?scrollY+target.getBoundingClientRect().top-top:y;scrollTo({left:x,top:Math.max(0,position),behavior:'instant'});
  requestAnimationFrame(()=>requestAnimationFrame(()=>{scrollRoot.style.overflowAnchor=anchoring;}));
 }
 function checkTask(){
  let correct=false,text='';const e=extra();
  if([1,2,4].includes(stage)){const task=currentTask();correct=selected===task.answer;text=task.feedback;}
  else if(stage===3){const parts=target().es.split(/\s+/);correct=norm(tokens.map(i=>parts[i]).join(' '))===norm(target().es);text=correct?'Верный порядок: '+target().es+' — '+target().ru+' '+e.explanation:'Сначала подумай о модели «'+e.pattern+'». Смысл: '+target().ru+' Убери слова из ответа и собери заново.';}
  else if(stage===5){correct=recallPlain(draft)===recallPlain(target().es);text=correct?(norm(draft)===norm(target().es)?'Ты вспомнил фразу: '+target().es:'Слова верные. Проверь знак ударения: '+target().es):'Для этого образца нужна фраза: '+target().es+' — '+target().ru+' Прочитай, закрой объяснение и напиши ещё раз.';}
  if(!correct&&[3,5].includes(stage)){const answer=stage===5?draft:tokens.map(i=>target().es.split(/\s+/)[i]).join(' '),specific=goals.feedback({day:contentDay(),stage,answer,target:target().es,correct});if(specific)text=specific+' Образец: '+target().es}result={correct,text};if(!correct){state.mistakes[state.day]=(state.mistakes[state.day]||0)+1;if(stage!==2){const p=stage===1?extra().examples[0]:target(),key='p:'+p.audio;if(cardCatalog[key])state.cards[key]={due:Date.now()+10*60000,interval:0,attempts:(state.cards[key]?.attempts||0)}}save()}adaptive.observe({id:'lesson:'+state.day+':'+contentDay()+':'+stage+':'+target().audio,day:contentDay(),audio:stage===2?null:(stage===1?extra().examples[0].audio:target().audio),skill:({1:'listening',2:'meaning',3:'order',4:'order',5:'recall'})[stage],correct,aided:hadHelp||learning.usedHelp()});learning.log('answer',state.day+':'+stage,correct);sound(correct?'correct':'wrong');renderLessonInteraction('[data-advance]');
 }
 function completeLesson(){
  if(!state.completed.includes(state.day))state.completed.push(state.day);state.ratings[state.day]=rating;
  const e=extra(),keys=e.examples.slice(0,3).map(p=>'p:'+p.audio);
  data.expanded.vocabulary.filter(w=>w.day===e.day).forEach(w=>keys.push('w:'+w.es));
  keys.forEach(k=>{if(cardCatalog[k]&&!state.cards[k])state.cards[k]={due:Date.now()+(rating==='retry'?10*60000:86400000),interval:0,attempts:0}});
  studio.lessonDone(state.day);learning.forget(state.day);learning.log('lesson',String(state.day),null);save();sound('finish');stopRecording();stage=7;render();window.scrollTo({top:0,behavior:'instant'});
 }
 function advance(){if(stage===2&&guidance()?.quizPrep&&!quizPrepSeen){quizPrepSeen=true;persistLesson();enterStep=true;render(true);scrollTo({top:0,behavior:'instant'});return}if(preparingOrigin()){advanceOrigin();return}if(stage===0){if(introCycles[introIndex]<2){introCycles[introIndex]++;introModelShown=false;enterStep=true;render(true);scrollTo({top:0,behavior:'instant'});return}if(introIndex<2){introIndex++;introModelShown=false;enterStep=true;render(true);scrollTo({top:0,behavior:'instant'});return}stage=1;resetTask()}else if(stage===6){if(rating)completeLesson();return}else if(result?.correct){stage++;resetTask()}else{checkTask();return}learning.newStage();enterStep=true;render(true);window.scrollTo({top:0,behavior:'instant'})}
 function words(){return library.render()}
 function startSet(keys){if(!keys.length){toast('В этом наборе пока нет карточек.');return}view='practice';practiceKind='review';reviewQueue=keys.filter(k=>cardCatalog[k]);reviewPos=0;reviewRevealed=false;render();window.scrollTo({top:0,behavior:'instant'});focusPractice('[data-reveal],h1')}
 function startScene(id){stopRecording(false);coach.enterScene(id);view='practice';practiceKind='scene';render();scrollTo(0,0);focusPractice()}
 function settings(){return `<section class="reading settings-page"><h1>Твой темп. Твой курс.</h1><p class="page-intro">Настрой звук, движение и чтение под себя. Всё сохраняется в этом браузере.</p><section><h2>Слушать и повторять</h2>${audioControls()}<p class="note">×0,5 — вдвое медленнее, с сохранением высоты голоса. Сначала разбери фразу, затем верни обычный темп. Оригинальные файлы не меняются.</p><label for="audio-volume">Громкость: <output id="volume-output">${Math.round(state.volume*100)}%</output><input type="range" id="audio-volume" min="0" max="1" step=".05" value="${state.volume}"></label>${controls()}</section><section><h2>Удобное чтение</h2><label>Оформление<select class="select" id="theme-choice">${[['light','Светлое'],['dark','Тёмное'],['system','Как на устройстве']].map(([id,label])=>`<option value="${id}" ${id===state.theme?'selected':''}>${label}</option>`).join('')}</select></label><label class="setting-check"><input type="checkbox" id="large-text" ${state.largeText?'checked':''}>Крупный текст</label></section><section><h2>Нагрузка в повторении</h2><label class="setting-check"><input id="adaptive-enabled" type="checkbox" ${state.adaptive.enabled?'checked':''}>Подбирать практику по ошибкам и подсказкам</label><p class="small">Анализ учебных ответов хранится здесь, на устройстве. Отдельных сервисов аналитики и передачи ответов нет. Самооценки имеют меньший вес, чем проверенные задания.</p><label>Карточек за один подход<select class="select" id="review-size">${[6,12,20].map(n=>`<option value="${n}" ${n===state.reviewSize?'selected':''}>${n} карточек</option>`).join('')}</select></label><p class="note">Начни с шести, если языки даются тяжело. Главная цель — вспомнить и произнести, а не просмотреть как можно больше.</p></section>${learning.settings()}${identity.html()}<section><h2>Приветствие Лумо</h2><button type="button" class="btn" data-welcome-open>Посмотреть заставку</button><p class="small">Запись человека включается по нажатию.</p></section>${native.html()}${progress.html()}${footer()}</section>`}
 function startReview(){view='practice';practiceKind='review';reviewQueue=dueKeys().slice(0,state.reviewSize);if(!reviewQueue.length)reviewQueue=Object.keys(state.cards).slice(0,8);if(!reviewQueue.length)reviewQueue=extra().examples.slice(0,3).map(p=>'p:'+p.audio);reviewPos=0;reviewRevealed=false;render();window.scrollTo({top:0,behavior:'instant'})}
 function rateReview(quality){const key=reviewQueue[reviewPos],card=state.cards[key]||{interval:0,attempts:0};const intervals=[1,3,7,14,30],level=Math.min(4,Math.max(0,Number(card.interval)||0));card.due=Date.now()+(quality==='again'?10*60000:quality==='help'?86400000:intervals[level]*86400000);card.interval=quality==='again'?0:quality==='help'?Math.max(0,level-1):Math.min(4,level+1);card.attempts=(card.attempts||0)+1;state.cards[key]=card;adaptive.observe({id:'review:'+key,day:cardCatalog[key]?.day||state.day,audio:cardCatalog[key]?.audio,skill:'recall',correct:quality==='easy',aided:quality==='help',self:true});learning.log('review',key,quality==='easy');studio.reviewRated(key);save();reviewPos++;reviewRevealed=false;sound(quality==='again'?'tap':'correct');render();focusPractice('[data-reveal],h1');}
 function practice(){
  if(practiceKind==='reader')return reader.html();if(practiceKind==='repair')return repair.html();if(practiceKind==='pathway')return bridgeReview.html()+pathway.html('pathway');if(practiceKind==='reading')return pathway.html('reading');
  if(practiceKind==='menu')return practiceMenu();return practiceMenu();}
 function practiceMenu(){
  if(practiceKind==='workbook')return workbook.html();
  if(practiceKind==='daily')return studio.html();
  if(practiceKind==='personal')return studio.personalHTML();
  if(practiceKind==='recordings')return recordings.html();
  if(practiceKind==='mission')return missions.html();
  if(practiceKind==='mastery')return mastery.html();
  if(practiceKind==='drill')return learning.drillHTML();
  if(practiceKind==='pronunciation')return speech.html();
  if(practiceKind==='scene')return coach.sceneView();
  if(practiceKind==='checkpoint')return coach.checkpointView();
  if(practiceKind==='review'){
   if(reviewPos>=reviewQueue.length)return `<section class="reading"><h1 class="main-title">Повторение завершено</h1><p class="page-intro">Трудные карточки вернутся через 10 минут, знакомые — через день и дальше. Интервалы — рабочая настройка, а оценку воспоминания отмечаешь ты.</p>${studio.nextButton()}<button type="button" class="btn ${studio.current()&&studio.current().step<4?'quiet':'primary'}" data-practice="menu">Выбрать практику</button>${footer()}</section>`;
   const p=cardCatalog[reviewQueue[reviewPos]];return `<section class="reading"><div class="section-head"><h1>Вспомни, затем проверь</h1><button class="btn quiet" type="button" data-practice="menu">${icon('arrow-left')}К практике</button></div><p class="page-intro">Карточка ${reviewPos+1} из ${reviewQueue.length}. Скажи испанскую фразу по смыслу, не подглядывая. Повтори её с новым личным фактом.</p><div class="review-card"><h2>${esc(p.ru)}</h2>${reviewRevealed?`<p class="spanish" lang="es" tabindex="-1" data-review-answer>${esc(p.es)}</p>${p.context?`<p class="small">${p.audio?'В записи':'Пример'}: <span lang="es">${esc(p.context)}</span></p>`:''}${playButton(p.audio,'Слушать ответ',true)}${audioCredit(p)}`:'<button type="button" class="btn primary" data-reveal>Показать ответ</button>'}</div>${audioControls()}${audioStatus()}${reviewRevealed?'<div class="review-controls"><button type="button" class="btn" data-review-rating="again">Не вспомнил</button><button type="button" class="btn" data-review-rating="help">С подсказкой</button><button type="button" class="btn primary" data-review-rating="easy">Вспомнил сам</button></div>':''}${footer()}</section>`;
  }
  if(practiceKind==='dialogue'){const e=extra();return `<section class="reading"><div class="section-head"><h1>Разговор с новой ролью</h1><button class="btn quiet" data-practice="menu" type="button">${icon('arrow-left')}К практике</button></div><p class="page-intro">${esc(e.mission)} Эти реплики — отдельные оригинальные записи. Переменные имена и факты проговори сам.</p>${audioControls()}<div class="dialogue">${e.examples.map(p=>`<div class="dialogue-line">${playButton(p.audio,'Слушать реплику '+p.es)}<div class="spanish" lang="es">${esc(p.es)}</div><p>${esc(p.ru)}</p></div>`).join('')}</div><h3>Раунд без текста</h3><p class="note">${esc(lesson().practice.own)}</p><p class="note">Смени имя, время или интерес. Не пытайся читать аудиопримеры как связный диалог: выбери подходящие реплики и добавь свои.</p>${audioStatus()}${footer()}</section>`}
  if(practiceKind==='sound'){const e=extra();return `<section class="reading sound-lab"><div class="section-head"><h1>Мастерская произношения</h1><button class="btn quiet" type="button" data-practice="menu">${icon('arrow-left')}К практике</button></div><p class="page-intro">Одна цель за подход: ударение, гласные или связь слов. Хорошо понятная речь — первый ориентир. Отсутствие акцента за 30 дней не обещаем.</p><section><h2>Слушай и замечай</h2>${audioControls()}<p class="note">${esc(e.pronunciation)}</p><div class="sound-compare">${e.examples.slice(0,2).map(phrase).join('')}</div>${audioStatus()}</section><section><h2>Повтори без опоры</h2><p class="note">1. Послушай целую фразу. 2. Повтори после окончания записи. 3. Закрой текст и скажи ещё раз. 4. Запиши себя. 5. Сравни одно отличие и повтори через несколько минут.</p>${recorderHTML()}</section><details><summary>Испанские звуки и русские привычки</summary><div><p>Гласные a, e, i, o, u обычно сохраняют ясное качество; не превращай безударное o в русское «а».</p><p>H не звучит. B и v не противопоставляются как русские «б/в». R и rr различаются: короткий удар кончика языка и несколько ударов. Ñ — единый звук; ll/y зависят от региона.</p><p>В выбранной кастильской записи c перед e/i и z часто /θ/. В большинстве вариантов Латинской Америки здесь /s/. Смешение регионов не оцениваем как ошибку.</p><p>Знак á/é/í/ó/ú показывает ударение. Без знака: слова на гласную, n или s обычно имеют ударение на предпоследнем слоге; остальные — на последнем.</p></div></details>${footer()}</section>`}
  if(practiceKind==='extra'){
   const l=practiceLesson(),e=extra(),tasks=[...l.practice.quiz,{question:'Как переводится «'+e.examples[2].es+'»?',options:e.examples.map(p=>p.ru),answer:2,feedback:e.examples[2].es+' — '+e.examples[2].ru}];
   if(practiceIndex>=tasks.length)return `<section class="reading"><h1>Ещё один круг пройден</h1><p class="page-intro">Теперь используй одну фразу в своей ситуации. Узнать ответ среди вариантов проще, чем вспомнить его в разговоре.</p><button class="btn primary" type="button" data-practice="dialogue">Перейти к разговору</button>${footer()}</section>`;
   const t=tasks[practiceIndex];return `<section class="reading"><div class="section-head"><h1>Дополнительная практика</h1><button class="btn quiet" type="button" data-practice="menu">${icon('arrow-left')}К практике</button></div><p class="page-intro">День ${state.day} · ${practiceIndex+1} из ${tasks.length}</p><h2>${esc(t.question)}</h2><div class="options">${t.options.map((o,i)=>`<button class="option" type="button" data-extra-option="${i}" aria-pressed="${selected===i}"><span class="option-num">${i+1}</span>${esc(o)}</button>`).join('')}</div>${practiceResult?`<div class="feedback ${practiceResult.correct?'':'wrong'}" role="status"><h3>${practiceResult.correct?'Верно':'Ещё одна попытка'}</h3><p>${esc(t.feedback)}</p></div>`:''}<button class="btn primary wide" type="button" data-extra-check ${selected===null?'disabled':''}>${practiceResult?.correct?'Следующее задание':'Проверить'}</button>${footer()}</section>`;
  }
  const option=(mode,title,desc,symbol,attr='data-practice-open')=>`<button type="button" class="hub-option" ${attr}="${mode}">${icon(symbol)}<span><strong>${title}</strong><small>${desc}</small></span>${icon('arrow-right')}</button>`;
  const group=(title,desc,symbol,options)=>`<details class="hub-group" data-fold="hub:${esc(title)}"><summary>${icon(symbol)}<span><strong>${title}</strong><small>${desc}</small></span></summary><div class="hub-links">${options}</div></details>`;
  return `<section class="page practice-hub"><h1>Разговор</h1><label class="chapter-pick">Урок для практики<select class="select" id="practice-day">${data.lessons.map(l=>`<option value="${l.day}" ${l.day===state.day?'selected':''}>День ${l.day} · ${esc(l.title)}</option>`).join('')}</select></label><section class="conversation-feature" aria-labelledby="conversation-title"><div><h2 id="conversation-title">${esc(practiceLesson().title)}</h2><p>${esc(guidance()?.scene||extra().mission)}</p><ol class="conversation-steps"><li><span>1</span>Слушай</li><li><span>2</span>Ответь</li><li><span>3</span>Смени факт</li></ol><button type="button" class="btn primary" data-practice-open="mission">Начать разговор ${icon('arrow-right')}</button><p class="conversation-caption">Разговор по подготовленной сцене. Подсказки доступны внутри.</p></div><button type="button" class="conversation-lumo" data-lumo="open" aria-label="Лумо: помощь с разговором">${mascot('wave')}</button></section><div class="practice-direct">${option('pronunciation','Сказать и сравнить','Слушай носителя · запиши себя · проверь слова','mic')+option('drill','Разогреть память','7 коротких заданий перед разговором','rotate-ccw')}</div><details class="page-fold practice-more" data-fold="practice:more"><summary>Другие тренировки и материалы</summary><div><div class="hub-links"><button type="button" class="hub-option" data-review-start>${icon('rotate-ccw')}<span><strong>Карточки к повторению</strong><small>${dueKeys().length?'К повторению: '+dueKeys().length:'Фразы по выбранной теме'}</small></span>${icon('arrow-right')}</button>${option('mastery','Проверить память через сутки','Три знакомые фразы без опоры','scan-text')+option('scene','Разговор на двоих','12 сцен · слушай и меняй роль','message-circle','data-practice')+option('sound','Разобрать произношение','Ударение, гласные и связь слов','headphones','data-practice')+option('dialogue','Своя реплика по образцу','Смени один факт в знакомой фразе','speech','data-practice')+option('workbook','Истории и мастерская','Чтение и задачи по теме дня','notebook-tabs')+option('personal','Мои фразы','Испанский с твоими именем и интересами','user-round')+option('recordings','Мои записи','Сравни свои голосовые попытки','archive')+option('extra','Квизы по теме','Вопросы с объяснениями','list-checks','data-practice')}</div>${journeyLinks()}${coach.checkpointLink(state.chapter)}</div></details>${footer()}</section>`;

 }
 function materials(){
  const categories=[['grammar','Грамматика','text-cursor-input'],['stories','Истории','book-open'],['video','Видео','play'],['guide','Как заниматься','route'],['methods','Методы обучения','lightbulb'],['audio','Записи и лицензии','headphones']];
  if(tab==='index')return `<section class="reading materials-index"><h1>Материалы</h1><nav class="material-entries" aria-label="Выбрать материал"><button type="button" data-tab="grammar">${icon('text-cursor-input')}<span>Грамматика</span>${icon('chevron-right')}</button><button type="button" data-open-reading>${icon('book-open')}<span>Чтение по уровням</span>${icon('chevron-right')}</button><button type="button" data-tab="video">${icon('play')}<span>Видео</span>${icon('chevron-right')}</button></nav><details class="material-reference"><summary>Как заниматься и источники</summary><nav class="material-entries" aria-label="Справочные материалы">${categories.filter(c=>!['grammar','video'].includes(c[0])).map(([id,label,symbol])=>`<button type="button" data-tab="${id}">${icon(symbol)}<span>${label}</span>${icon('chevron-right')}</button>`).join('')}</nav></details>${footer()}</section>`;
  let body='';
  if(tab==='guide')body=`<article><h2>Как заниматься 35 минут</h2><ol><li>Около 5 минут — вернуть из памяти до шести знакомых карточек. В первом занятии этот шаг пропускается.</li><li>Около 13 минут — разобрать записи носителя и модель, затем пройти слух, выбор, порядок слов и воспоминание. Первые три фразы активно, четвёртая на понимание.</li><li>Около 10 минут — разговорная миссия: слушать без текста, отвечать и реагировать на новую деталь. Текст, смысл и разбор открывай по необходимости.</li><li>Около 7 минут — собственный факт, деталь и встречный вопрос. По желанию запиши голос; отметь попытку и что повторить.</li></ol><button type="button" class="btn" data-practice-open="daily">Открыть моё занятие ${icon('arrow-right')}</button><p>Если времени мало, проведи 10 минут повторения и речи. Это облегчённый день, а не выполненный полный урок.</p></article><article><h2>От слов к предложению</h2><p>Сначала смысл: кто, что делает, с чем или где. Потом модель: me gusta + действие; voy a + инфинитив; no + глагол. Затем личный факт. Не переводить русское предложение слово за словом.</p><p>Работай с сочетаниями: un poco de español, a las dos, por favor. Отдельное слово легче употребить правильно, когда знакомы его соседние слова.</p></article><article><h2>Как поддерживать разговор</h2><p>Ответ → одна деталь → встречный вопрос. Если не понял — уточнить. Если ошибся — исправить одну фразу после небольшого обмена и снова использовать её.</p></article><article><h2>Настройки</h2><p>Звуки интерфейса и движение можно выключить отдельно. Озвучка запускается только твоим нажатием.</p>${controls()}</article>`;
  if(tab==='stories')body=workbook.entry();
  if(tab==='grammar')body=coach.grammar();
  if(tab==='methods')body=data.methods.map(m=>`<article><h2>${esc(m.title)}</h2><p>${esc(m.technique)}</p><p>${esc(m.purpose)}</p><p class="small">${esc(m.evidence)}</p><a href="${esc(m.url)}" target="_blank" rel="noopener">Источник метода</a></article>`).join('');
  if(tab==='video')body=window.VamosVideos.create({data,esc,icon}).html();
  if(tab==='audio')body=`<article><h2>Живой голос в курсе</h2><p>${Object.keys(data.expanded.audio).length} записей фраз Tatoeba и ${Object.keys(data.wordAudio.clips).length} записей отдельных слов Lingua Libre / Wikimedia Commons. У слова есть прямая кнопка озвучки, если его точная запись доступна; остальные примеры звучат в подписанном контексте. Переменные модели и самостоятельно введённые ответы не озвучиваются синтезом.</p><p>Основной автор arh описывает себя как носителя испанского из Кастилии. Среди записей может быть другой автор; у каждой доступны источник и лицензия.</p><p>Курс предназначен для личного некоммерческого обучения. Аудиофайлы не изменены. Записи слов Rodelar — CC BY-SA 4.0; источники и лицензии указаны отдельно. Тексты испанских примеров — Tatoeba, CC BY 2.0 FR; русские пояснения и переводы написаны для курса.</p><a href="https://tatoeba.org/en/user/profile/arh" target="_blank" rel="noopener">Профиль и регион автора</a> · <a href="https://tatoeba.org/en/downloads" target="_blank" rel="noopener">Условия источника</a></article>`+Object.entries({...data.expanded.audio,...data.wordAudio.clips}).map(([audioId,a])=>`<article><h3 lang="es">${esc(a.text)}</h3>${playButton(audioId,'Слушать '+a.text,true)}<p class="small">${esc(a.speaker)} · <a href="${esc(a.licenseUrl)}" target="_blank" rel="noopener">${esc(a.license)}</a> · без изменений</p><a href="${esc(a.sentenceUrl)}" target="_blank" rel="noopener">Запись в источнике</a></article>`).join('')+audioStatus();
  return `<section class="reading material-detail"><button type="button" class="btn quiet route-return" data-tab="index">${icon('arrow-left')}К материалам</button><h1>${categories.find(c=>c[0]===tab)?.[1]||'Материалы'}</h1>${body}${footer()}</section>`;
 }
 coach=window.VamosCoach.create({data,state,esc,icon,playButton,audioControls,audioCredit,recorderHTML,footer,save,render,toast,stopRecording});

 libraryPractice=window.VamosLibraryPractice.create({state,data,esc,icon,playButton,audioControls,audioStatus,audioCredit,footer,save,render,toast,sound,observe:(x,r)=>{adaptive.observe({id:'library-recall:'+x.id,day:x.day,audio:x.audio,skill:'recall',correct:r.correct,aided:r.aided});learning.log('answer','library-recall:'+x.id,r.correct&&!r.aided,x.day);const old=state.cards[x.reviewKey];state.cards[x.reviewKey]={due:Date.now()+(r.correct&&!r.aided?86400000:600000),interval:r.correct&&!r.aided?Math.max(0,old?.interval||0):0,attempts:(old?.attempts||0)+1};save()}});
 library=window.VamosLibrary.create({practice:libraryPractice,observeQuiz:(x,correct,aided)=>{adaptive.observe({id:'text:'+x.id,day:x.day,audio:null,skill:'meaning',correct,aided});learning.log('answer','text:'+x.id,correct,x.day);if(!correct){for(const p of x.lines.slice(0,3)){const key='p:'+p.audio;state.cards[key]={...(state.cards[key]||{}),due:Date.now()+600000,interval:0}}save()}},data,state,esc,plain,icon,coach,startScene,playButton,audioCredit,audioStatus,audioControls,recorderHTML,footer,save,toast,sound,render,startSet,openLesson,playSequence,stopRecording});
 navigation=window.VamosNavigation.create({esc,icon,openLesson,next:()=>learning?.next()||state.day,nextSession:()=>studio?.continuation(),startStudy:()=>studio?.begin(),onOpen:()=>{if(view==='lesson'&&stage<7)persistLesson();speech?.stop();stopAudio();stopRecording(false)},view:()=>view,practice:()=>practiceKind,day:()=>state.day});
 adaptive=window.VamosAdaptive.create({data,state,save});
